package com.bank.coverage;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class CitiesSetDemo {
    private static final Logger log = Logger.getLogger("Coverage");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", "Mumbai"),
            new Employee("Amit", "IT", "Mumbai"),   // duplicate city within IT
            new Employee("Karan", "IT", "Delhi"),
            new Employee("Priya", "Sales", "Mumbai"));
        CoverageService service = new CoverageService();

        Map<String, Set<String>> cities = service.citiesByDepartment(staff);
        cities.forEach((dept, set) -> log.info(() -> dept + " → " + set));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final String department;
    private final String city;
    Employee(String name, String department, String city) {
        this.name = name; this.department = department; this.city = city;
    }
    String getDepartment() { return department; }
    String getCity() { return city; }
}

// ─── Would be in service/CoverageService.java ───
class CoverageService {
    Map<String, Set<String>> citiesByDepartment(List<Employee> staff) {
        return staff.stream()
            .filter(e -> e.getDepartment() != null && e.getCity() != null)
            .collect(groupingBy(Employee::getDepartment,
                mapping(Employee::getCity, toSet())));   // city → Set per dept (dedupe)
    }
}
